import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"技术是交易的真谛吗？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易认知/报着不亏钱的目的交易.md","filePath":"stock/交易认知/报着不亏钱的目的交易.md"}'),r={name:"stock/交易认知/报着不亏钱的目的交易.md"};function s(n,p,_,c,i,d){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="技术是交易的真谛吗" tabindex="-1">技术是交易的真谛吗？ <a class="header-anchor" href="#技术是交易的真谛吗" aria-label="Permalink to &quot;技术是交易的真谛吗？&quot;">​</a></h1><p>我来说点不一样的。</p><p>首先，我认为交易的本质是赌，因为行情具有很强的随机性，未来的走势和价格谁也无法精准预测。</p><p>既然是赌，那么交易的真谛是什么呢？有的人认为资金管理很重要，把一笔钱分成100份，慢慢去赌。</p><p>我可以很不客气的说，只要你的赌法是错的，资金管理只是延长你的爆仓时间，让你死的慢一点罢了。</p><p>你所追求的，其实只是拉长爆仓时间，看看中间有没有几次撞大运，让你扭亏为盈。</p><p>有的人认为心态很重要，你说一个亏货能心态好到哪里去吗？好的心态一定是通过赚钱来培养的。</p><p>谁能天天亏钱心态还很好，除非家里有矿。所以心态肯定不是交易的真谛，是你交易成功后的一个正循环罢了。</p><p>技术是交易的真谛吗？</p><p>也不是，技术只是你交易的手段罢了。</p><p>有的人用基本面做交易，完全不用技术，那他们就碰不到交易的真谛了吗？</p><p>那可未必。</p><p>说了这么多，我认为的交易真谛是什么？</p><p>其实是你参与这个游戏的目的。</p><p>我参与这个游戏的目的是什么？</p><p><strong>是不亏钱。</strong></p><p>有的人可能觉得很可笑，目的不是赚钱吗？</p><p>当然没错，但是你不能抱着要赚钱的心来玩这个游戏，因为你会滋生出各种各样的问题。</p><p>那抱着不亏钱的心玩这个游戏，能得到什么好处？</p><p>第一就是错过行情没那么难过，</p><p>第二个是开始学会等待属于自己的行情，</p><p>第三是把风险看的最重，利润只是玩这个游戏的奖赏罢了。</p>',22)]))}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
